// مراقبة مقياس Largest Contentful Paint (LCP)
const observer = new PerformanceObserver((entryList) => {
  const entries = entryList.getEntries();
  const lastEntry = entries[entries.length - 1]; // أحدث عنصر مرشح كـ LCP

  console.log(`🎯 عنصر الـ LCP: ${lastEntry.element?.tagName}, زمن الرندرة: ${lastEntry.startTime.toFixed(2)}ms`);

  // إرسال البيانات لنظام التحليلات / RUM
  // sendToAnalytics({ metric: 'LCP', value: lastEntry.startTime, element: lastEntry.element?.tagName });
});

// تسجيل المظاهر الخاصة بـ LCP مع buffering
observer.observe({ type: 'largest-contentful-paint', buffered: true });
